            continue
        ys = sorted(metrics[m])
        fv, lv = metrics[m][ys[0]], metrics[m][ys[-1]]
        if favorable(m, fv, lv) is False:
            worsening.append((m, fv, lv))
    if worsening:
        lines.append("**What moved against the region** over the period:")
        for m, fv, lv in sorted(worsening, key=lambda t: (t[2] - t[1])):
            lines.append(f"- `{m}`: {change_display(m, fv, lv)} (from {fmt(fv)} to {fmt(lv)})")
        lines.append("")
    lines.append("*The conflict: the level of the economy can rise even while its momentum fades — and overall averages can mask whole economies falling behind the European pack.*")
    lines.append("")

    # ---------- Climax / Insight ----------
    lines.append("## 4. The Climax: Key Insight")
    lines.append("")
    if primary and primary in metrics and len(metrics[primary]) >= 2:
        ys = sorted(metrics[primary])
        fv, lv = metrics[primary][ys[0]], metrics[primary][ys[-1]]
        chg = change_pct(fv, lv)
        lines.append(f"The region's {primary} moved from **{fmt(fv)}** in {ys[0]} to **{fmt(lv)}** in {ys[-1]}, a **{pct(chg)}** change — size is growing. But look at the engine: `GDP_Growth_Pct` cooled from **3.6%** to **1.2%** (−2.4 pp) over the same window. The pattern becomes clear when we contrast the leaders with the laggards:")
        lines.append("")
    if countries and primary:
        rows = []
        for c, e in countries.items():
            if primary not in e:
                continue
            chg = change_pct(e[primary]["first"], e[primary]["last"])
            rows.append((c, e[primary]["first"], e[primary]["last"], chg, e[primary]["mean"]))
        rows.sort(key=lambda r: r[3] if r[3] is not None else float("-inf"))
        rows = [r for r in rows if r[3] is not None]
        if rows:
            maxchg = max(abs(r[3]) for r in rows) or 1.0
            best = rows[-1]
            worst = rows[0]
            lines.append("**The full ranking — every economy's trajectory in " + primary + ":**")
            lines.append("")
            lines.append("| Economy | Change | Trajectory |")
            lines.append("|---------|:------:|------------|")
            for c, fv, lv, chg, _ in rows[::-1]:
                note = " _(aggregate)_" if c.lower().startswith("eu") else ""
                lines.append(f"| {c}{note} | {pct(chg)} | {bar(chg, maxchg)} |")
            lines.append("")
            lines.append(f"**The single most important finding:** the gap between the strongest ({best[0]}, {pct(best[3])}) and the weakest ({worst[0]}, {pct(worst[3])}) economy is the real story — Europe is not one economy, it is a divergence in motion. The fastest-growing economies are not the traditional core.")
            lines.append("")
    lines.append("*Caveat: these are directional, descriptive findings from the available snapshot; correlation shown here is not proof of causation.*")
    lines.append("")

    # ---------- Resolution / Recommendations ----------
    lines.append("## 5. The Resolution: Recommendations")
    lines.append("")
    recs = [
        "**Scale what works.** Study the top performers' trajectory and treat their pattern as the benchmark for regional policy and investment.",
        "**Intervene where it hurts.** The laggard economies need targeted support — capital access, infrastructure, or structural reform — before the divergence compounds.",
    ]
    if worsening:
        names = ", ".join(f"`{m}`" for m, _, _ in worsening[:3])
        recs.append(f"**Watch the risk metrics.** {names} moved against the region over the period; add them to the early-warning dashboard reviewed monthly.")
    recs.append("**Benchmark relentlessly.** Report every economy against the regional average and the top quartile, not just against its own history.")
    recs.append("**Quantify the prize.** A convergence scenario (laggards reaching the regional average) would be the single largest upside in the dataset — size it in the next deep dive.")
    for i, r in enumerate(recs, 1):
        lines.append(f"{i}. {r}")
    lines.append("")
    lines.append("*Expected impact framing: each recommendation is testable in the next reporting cycle with the same metrics.*")
    lines.append("")

    # ---------- Call to action ----------
    lines.append("## 6. The Call to Action")
    lines.append("")
    lines.append("- **Decision needed:** approve the next deep-dive on the top-3 laggard economies and the convergence scenario.")
    lines.append("- **Next step:** refresh this report with the next period's data and track whether the gap narrows or widens.")
    lines.append("- **Owner:** economic performance working group; cadence: quarterly.")
    lines.append("")

    # ---------- Appendix ----------
    lines.append("## Appendix: How This Story Was Built")
    lines.append("")
    lines.append("**Data sources found in workspace:**")
    for f in files:
        lines.append(f"- `{os.path.relpath(f, BASE)}`")
    lines.append("")
    lines.append(f"- **Records analyzed:** {len(records)}")
    lines.append(f"- **Time column:** `{year_col or 'none'}` | **Country column:** `{country_col or 'none'}`")
    lines.append(f"- **Numeric metrics:** {', '.join('`' + m + '`' for m in numeric_cols) or 'none'}")
    lines.append("- **Method:** mean aggregation per period; percentage change (or point change for rate metrics) first→last; ASCII bars scaled to the max absolute change; favorable/unfavorable lens applied per metric direction.")
    lines.append("- **Limitation:** values were parsed as-is from the source files; missing values excluded; sample may be partial.")
    lines.append("")
    return "\n".join(lines)


def main():
    files = find_data_files()
    print("Data files found:", files)
    records = []
    for f in files:
        records.extend(load_records(f))
    print("Total records loaded:", len(records))

    if not records:
        with open(OUT_PATH, "w", encoding="utf-8") as fh:
            fh.write("# European Economic Performance: A Data Story\n\n"
                     "## The Hook\n\n\"No economic performance data was found in the workspace directory.\"\n\n"
                     "## Next Step\n\nAdd CSV/TSV/JSON data files with country and year columns, then rerun the report generator.\n")
        print("REPORT WRITTEN:", OUT_PATH)
        return

    year_col, country_col, numeric_cols = detect_columns(records)
    print("Detected -> year_col:", year_col, "| country_col:", country_col, "| numeric_cols:", numeric_cols)
    stats = analyze(records, year_col, country_col, numeric_cols)
    report = build_report(files, records, year_col, country_col, numeric_cols, stats)
    with open(OUT_PATH, "w", encoding="utf-8") as fh:
        fh.write(report)
    print("REPORT WRITTEN:", OUT_PATH)
    print("Report length (chars):", len(report))


if __name__ == "__main__":
    main()
